/** Значения контролов формы: строки (как в DOM), кроме ограниченных списков. */
export interface FormValues {
  title: string;
  type: SessionType;
  date: string;
  time: string;
  duration: string;
  capacity: string;
  coachId: string;
  locationName: string;
  locationAddress: string;
  visibility: Visibility;
  description: string;
  trainerNotes: string;
}

export type FieldName = keyof FormValues;

/** Ключ ошибки: поля формы плюс `startsAt` (ошибка пары Date/Start time). */
export type ErrorKey = FieldName | "startsAt";
export type FormErrors = Partial<Record<ErrorKey, string>>;

/** Порядок ошибок = порядок полей в DOM (для фокуса на первое невалидное). */
export const ERROR_ORDER: readonly ErrorKey[] = [
  "title",
  "type",
  "date",
  "time",
  "startsAt",
  "duration",
  "capacity",
  "coachId",
  "locationName",
  "locationAddress",
  "visibility",
  "description",
  "trainerNotes",
];

export const INITIAL_VALUES: FormValues = {
  title: "",
  type: "training",
  date: "",
  time: "",
  duration: "",
  capacity: "",
  coachId: "",
  locationName: "",
  locationAddress: "",
  visibility: "public",
  description: "",
  trainerNotes: "",
};

export function isDirty(values: FormValues): boolean {
  return (Object.keys(INITIAL_VALUES) as FieldName[]).some((key) => values[key] !== INITIAL_VALUES[key]);
}

/** Ключ серверного `fieldErrors`, который снимается при редактировании поля. */
export const FIELD_SERVER_KEY: Record<FieldName, string> = {
  title: "title",
  type: "type",
  date: "startsAt",
  time: "startsAt",
  duration: "durationMinutes",
  capacity: "capacity",
  coachId: "coachId",
  locationName: "locationName",
  locationAddress: "locationAddress",
  visibility: "visibility",
  description: "description",
  trainerNotes: "trainerNotes",
};

const SERVER_KEY_TO_ERROR: Record<string, ErrorKey> = {
  title: "title",
  type: "type",
  startsAt: "startsAt",
  durationMinutes: "duration",
  capacity: "capacity",
  coachId: "coachId",
  locationName: "locationName",
  locationAddress: "locationAddress",
  visibility: "visibility",
  description: "description",
  trainerNotes: "trainerNotes",
};

export interface SplitServerErrors {
  /** Ошибки, у которых есть поле. */
  fields: FormErrors;
  /** Тексты ключей без поля: уходят в блок формы (D-7). */
  unmatched: string[];
}

export function splitServerErrors(fieldErrors: Record<string, string>): SplitServerErrors {
  const fields: FormErrors = {};
  const unmatched: string[] = [];
  for (const [key, message] of Object.entries(fieldErrors)) {
    const target = Object.hasOwn(SERVER_KEY_TO_ERROR, key) ? SERVER_KEY_TO_ERROR[key] : undefined;
    if (target === undefined) unmatched.push(message);
    else fields[target] = message;
  }
  return { fields, unmatched };
}

/** Запрос API из уже проверенных значений; `null`, если дата и время не собираются в `startsAt`. */
export function toRequest(values: FormValues): CreateSessionRequest | null {
  const start = localToIsoUtc(values.date, values.time);
  if (!start.ok) return null;
  const description = values.description.trim();
  const trainerNotes = values.trainerNotes.trim();
  const request: CreateSessionRequest = {
    title: values.title.trim(),
    type: values.type,
    startsAt: start.iso,
    durationMinutes: Number(values.duration.trim()),
    coachId: values.coachId,
    locationName: values.locationName.trim(),
    locationAddress: values.locationAddress.trim(),
    capacity: Number(values.capacity.trim()),
    visibility: values.visibility,
  };
  if (description !== "") request.description = description;
  if (trainerNotes !== "") request.trainerNotes = trainerNotes;
  return request;
}
import { useCallback, useRef, useState } from "react";
import { createSession } from "../../shared/api/client.ts";
import type { ClientError } from "../../shared/api/errors.ts";
import type { CoachSummary, CreateSessionRequest, SessionDetails } from "../../shared/api/types.ts";
import type { CoachesStatus } from "./useCoaches.ts";

export type CreateStatus = "idle" | "pending" | "success" | "error";

export type SubmitOutcome =
  | { kind: "ignored" }
  | { kind: "blocked" }
  | { kind: "success"; session: SessionDetails }
  | { kind: "error"; error: ClientError };

export interface CoachesGuard {
  status: CoachesStatus;
  coaches: readonly CoachSummary[];
}

export interface UseCreateSessionResult {
  status: CreateStatus;
  session: SessionDetails | null;
  error: ClientError | null;
  /** Серверные `fieldErrors` по ключам контракта. */
  fieldErrors: Record<string, string>;
  submit: (request: CreateSessionRequest) => Promise<SubmitOutcome>;
  /** Снимает серверную ошибку поля при его редактировании. */
  clearFieldError: (serverKey: string) => void;
  reset: () => void;
}

const NO_ERRORS: Record<string, string> = {};

/**
 * Отправка формы. Guard (api-integration, раздел 9): `createSession` не вызывается, пока список
 * тренеров не загружен успешно или `coachId` не входит в него. Флаг pending (ref, срабатывает
 * синхронно) блокирует повторный вызов; POST не отменяется.
 */
export function useCreateSession(guard: CoachesGuard): UseCreateSessionResult {
  const [status, setStatus] = useState<CreateStatus>("idle");
  const [session, setSession] = useState<SessionDetails | null>(null);
  const [error, setError] = useState<ClientError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>(NO_ERRORS);
  const pending = useRef(false);
  const { status: coachesStatus, coaches } = guard;

  const submit = useCallback(
    async (request: CreateSessionRequest): Promise<SubmitOutcome> => {
      if (pending.current) return { kind: "ignored" };
      if (coachesStatus !== "success" || !coaches.some((coach) => coach.id === request.coachId)) {
        return { kind: "blocked" };
      }
      pending.current = true;
      setStatus("pending");
      setError(null);
      setFieldErrors(NO_ERRORS);
      const result = await createSession(request);
      pending.current = false;
      if (result.ok) {
        setSession(result.data);
        setStatus("success");
        return { kind: "success", session: result.data };
      }
      // Недостижимо: у POST нет signal (решение 10=A). Ветка оставлена, потому что тип результата
      // клиента `ApiResult` (публичный контракт shared/api) включает `cancelled`.
      if (result.cancelled) {
        setStatus("idle");
        return { kind: "ignored" };
      }
      setError(result.error);
      setFieldErrors(result.error.kind === "api" ? (result.error.fieldErrors ?? NO_ERRORS) : NO_ERRORS);
      setStatus("error");
      return { kind: "error", error: result.error };
    },
    [coachesStatus, coaches],
  );

  const clearFieldError = useCallback((serverKey: string) => {
    setFieldErrors((current) => {
      if (!Object.hasOwn(current, serverKey)) return current;
      const { [serverKey]: _removed, ...rest } = current;
      return rest;
    });
  }, []);

  const reset = useCallback(() => {
    if (pending.current) return;
    setStatus("idle");
    setSession(null);
    setError(null);
    setFieldErrors(NO_ERRORS);
  }, []);

  return { status, session, error, fieldErrors, submit, clearFieldError, reset };
}

