import { useEffect, useMemo, useSyncExternalStore } from "react";

// Тонкий слой History API. Доменных имён параметров не знает.

const NAVIGATE_EVENT = "app:navigate";

export interface NavigateOptions {
  replace?: boolean;
  state?: unknown;
}

export interface RouterLocation {
  pathname: string;
  search: string;
}

export function navigate(to: string, options: NavigateOptions = {}): void {
  if (options.replace) {
    window.history.replaceState(options.state ?? null, "", to);
  } else {
    window.history.pushState(options.state ?? null, "", to);
  }
  window.dispatchEvent(new Event(NAVIGATE_EVENT));
}

/** Состояние текущей записи истории (флаг «из приложения / из списка» задаёт вызывающий код). */
export function readHistoryState(): unknown {
  return window.history.state;
}

/** Признак записи истории, созданной переходом из списка (A-11). Теряется при открытии в новой вкладке. */
export const FROM_LIST_STATE = { fromList: true } as const;

/** `true`, если текущая запись истории открыта переходом из списка и предыдущая запись принадлежит списку. */
export function cameFromList(): boolean {
  const state: unknown = window.history.state;
  return typeof state === "object" && state !== null && "fromList" in state && state.fromList === true;
}

/** Шаг назад по истории браузера. */
export function goBack(): void {
  window.history.back();
}

function subscribe(onChange: () => void): () => void {
  window.addEventListener("popstate", onChange);
  window.addEventListener(NAVIGATE_EVENT, onChange);
  return () => {
    window.removeEventListener("popstate", onChange);
    window.removeEventListener(NAVIGATE_EVENT, onChange);
  };
}

function getSnapshot(): string {
  return window.location.pathname + window.location.search;
}

/** Текущие path и search с подпиской на popstate и собственные навигации. */
export function useLocation(): RouterLocation {
  const snapshot = useSyncExternalStore(subscribe, getSnapshot);
  return useMemo(() => {
    const i = snapshot.indexOf("?");
    return i === -1
      ? { pathname: snapshot, search: "" }
      : { pathname: snapshot.slice(0, i), search: snapshot.slice(i) };
  }, [snapshot]);
}

function normalizePath(pathname: string): string {
  return pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
}

/** Сопоставление пути с шаблоном вида `/sessions/:id`. `null`, если путь не подходит. */
export function matchPath(pattern: string, pathname: string): Record<string, string> | null {
  const want = normalizePath(pattern).split("/");
  const have = normalizePath(pathname).split("/");
  if (want.length !== have.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < want.length; i += 1) {
    const w = want[i];
    const h = have[i];
    if (w.startsWith(":")) {
      if (h === "") return null;
      try {
        params[w.slice(1)] = decodeURIComponent(h);
      } catch {
        return null;
      }
    } else if (w !== h) {
      return null;
    }
  }
  return params;
}

export function getSearchParam(search: string, name: string): string | null {
  return new URLSearchParams(search).get(name);
}

/**
 * Возвращает новый search (`?a=b` или пустую строку). `null`/`undefined`/`""` удаляют параметр,
 * остальные параметры сохраняются нетронутыми.
 */
export function updateSearch(
  search: string,
  updates: Record<string, string | null | undefined>,
): string {
  const params = new URLSearchParams(search);
  for (const [name, value] of Object.entries(updates)) {
    if (value === null || value === undefined || value === "") {
      params.delete(name);
    } else {
      params.set(name, value);
    }
  }
  const next = params.toString();
  return next ? `?${next}` : "";
}

/** Неизвестный путь -> `replace` на `fallback` с сохранением search. */
export function useRedirectUnknown(knownPatterns: readonly string[], fallback: string): void {
  const { pathname, search } = useLocation();
  const known = knownPatterns.some((pattern) => matchPath(pattern, pathname) !== null);
  useEffect(() => {
    if (!known) navigate(`${fallback}${search}`, { replace: true });
  }, [known, fallback, search]);
}
import { useState } from "react";
import "../App.css";
import {
  FROM_LIST_STATE,
  matchPath,
  navigate,
  readHistoryState,
  useLocation,
  useRedirectUnknown,
} from "../shared/router/index.ts";
import { CreateSessionDialog } from "../features/create-session/CreateSessionDialog.tsx";
import { SessionDetailsDialog } from "../features/sessions/SessionDetailsDialog.tsx";
import { SessionsPage } from "../features/sessions/SessionsPage.tsx";
import { clearFilters, hasActiveFilters, readFilters } from "../features/sessions/filters.ts";

const KNOWN_ROUTES = ["/sessions", "/sessions/:id"] as const;

function App() {
  const { pathname, search } = useLocation();
  useRedirectUnknown(KNOWN_ROUTES, "/sessions");
  // Форма создания не имеет URL: открытость локальная. reloadKey перезапрашивает список (D-4).
  const [createOpen, setCreateOpen] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);

  const detailsId = matchPath("/sessions/:id", pathname)?.id ?? null;
  const known = detailsId !== null || matchPath("/sessions", pathname) !== null;
  if (!known) return null;

  function openCreate(): void {
    // Детали модальны, фон инертен; форма поверх них не открывается.
    if (detailsId === null) setCreateOpen(true);
  }

  function closeCreate({ refetch }: { refetch: boolean }): void {
    setCreateOpen(false);
    if (refetch) setReloadKey((n) => n + 1);
  }

  function openCreatedSession(id: string): void {
    setCreateOpen(false);
    navigate(`/sessions/${encodeURIComponent(id)}${search}`, { state: FROM_LIST_STATE });
  }

  function resetFilters(): void {
    navigate(`${pathname}${clearFilters(search)}`, { replace: true, state: readHistoryState() });
  }

  // Список остаётся смонтированным под диалогом; видимость диалога деталей выводится из URL (D-1).
  return (
    <>
      <SessionsPage onCreateSession={openCreate} reloadKey={reloadKey} />
      {detailsId === null ? null : <SessionDetailsDialog key={detailsId} id={detailsId} />}
      {createOpen ? (
        <CreateSessionDialog
          filtersActive={hasActiveFilters(readFilters(search))}
          onClose={closeCreate}
          onCreated={() => setReloadKey((n) => n + 1)}
          onOpenSession={openCreatedSession}
          onClearFilters={resetFilters}
        />
      ) : null}
    </>
  );
}

export default App

